  [string]$Out = ''
)
# 抓一张全屏（含多显示器）。纯 ASCII 源码。用 user32 取虚拟屏幕尺寸，绕开 WinForms。
Add-Type -AssemblyName System.Drawing
if (-not ('Win32Screen' -as [type])) {
  Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class Win32Screen {
  [DllImport("user32.dll")] public static extern int GetSystemMetrics(int n);
}
'@
}
$x = [Win32Screen]::GetSystemMetrics(76)
$y = [Win32Screen]::GetSystemMetrics(77)
$w = [Win32Screen]::GetSystemMetrics(78)
$h = [Win32Screen]::GetSystemMetrics(79)
if ($w -le 0 -or $h -le 0) { $x = 0; $y = 0; $w = 1920; $h = 1080 }

$bmp = New-Object System.Drawing.Bitmap $w, $h
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.CopyFromScreen((New-Object System.Drawing.Point $x, $y), [System.Drawing.Point]::Empty, (New-Object System.Drawing.Size $w, $h))
$g.Dispose()

if (-not $Out) {
  $dir = Join-Path $env:USERPROFILE '.dsh-qq\media\shots'
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $Out = Join-Path $dir ('shot-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.png')
}
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
$bmp.Dispose()
Write-Output ("{0}|{1}x{2}" -f $Out, $w, $h)
", "file_path": "C:\Users\九幽\.dsh-qq\scripts\shot.ps1"}

