{"content": "#!/usr/bin/env node
// 晚晚的手机手：adb 包一层，够用就行。
//   node phone.mjs shot [--out path]        截屏
//   node phone.mjs tap X Y                  点
//   node phone.mjs swipe X1 Y1 X2 Y2 [ms]   滑
//   node phone.mjs key KEYCODE              按键（HOME/BACK/POWER...）
//   node phone.mjs text "abc123"            输英文数字（中文要走输入法）
//   node phone.mjs ui                       导出控件树（文字 + 坐标）
//   node phone.mjs open <包名|包名/Activity>  开应用
//   node phone.mjs apps [关键词]             列已装包名
//   node phone.mjs home | back | wake | sleep
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const ADB = 'C:/Users/九幽/tools/platform-tools/adb.exe';
const OUT = 'C:/Users/九幽/.dsh-qq/media/phone';

const adb = (args, opts = {}) => {
  const r = execFileSync(ADB, args, { encoding: opts.binary ? 'buffer' : 'utf8', timeout: 60000 });
  return r;
};
const args = process.argv.slice(2);
const cmd = args[0];
const rest = args.slice(1);
const stamp = () => new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);

function ensureDevice() {
  const out = adb(['devices']);
  if (!/\tdevice\s*$/m.test(out)) {
    const st = out.includes('unauthorized') ? 'unauthorized（手机上要点允许）' : '没连上';
    console.error('设备状态：' + st);
    process.exit(2);
  }
}

try {
  switch (cmd) {
    case 'shot': {
      ensureDevice();
      const i = rest.indexOf('--out');
      const out = i >= 0 ? rest[i + 1] : path.join(OUT, `phone-${stamp()}.png`);
      fs.mkdirSync(path.dirname(out), { recursive: true });
      const buf = adb(['exec-out', 'screencap', '-p'], { binary: true });
      fs.writeFileSync(out, buf);
      console.log(out);
      break;
    }
    case 'tap': {
      ensureDevice();
      adb(['shell', 'input', 'tap', rest[0], rest[1]]);
      console.log(`tap ${rest[0]},${rest[1]}`);
      break;
    }
    case 'swipe': {
      ensureDevice();
      adb(['shell', 'input', 'swipe', rest[0], rest[1], rest[2], rest[3], rest[4] || '300']);
      console.log(`swipe ${rest.slice(0, 4).join(',')}`);
      break;
    }
    case 'key': {
      ensureDevice();
      const map = { home: 'KEYCODE_HOME', back: 'KEYCODE_BACK', wake: 'KEYCODE_WAKEUP', sleep: 'KEYCODE_SLEEP', recent: 'KEYCODE_APP_SWITCH', enter: 'KEYCODE_ENTER' };
      const k = map[rest[0]] || rest[0];
      adb(['shell', 'input', 'keyevent', k]);
      console.log(k);
      break;
    }
    case 'text': {
      ensureDevice();
      adb(['shell', 'input', 'text', rest.join(' ').replace(/ /g, '%s')]);
      console.log('typed');
      break;
    }
    case 'ui': {
      ensureDevice();
      adb(['shell', 'uiautomator', 'dump', '/sdcard/ui.xml']);
      const xml = adb(['shell', 'cat', '/sdcard/ui.xml']);
      fs.mkdirSync(OUT, { recursive: true });
      const p = path.join(OUT, `ui-${stamp()}.xml`);
      fs.writeFileSync(p, xml, 'utf8');
      // 顺手把能认的控件摘成人话
      const nodes = [...xml.matchAll(/<node[^>]*>/g)].map((m) => m[0]);
      const lines = [];
      for (const n of nodes) {
        const text = (n.match(/text="([^"]*)"/) || [])[1] || '';
        const desc = (n.match(/content-desc="([^"]*)"/) || [])[1] || '';
        const bounds = (n.match(/bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"/) || []).slice(1).map(Number);
        const clickable = /clickable="true"/.test(n);
        if ((!text && !desc) || bounds.length < 4) continue;
        const cx = Math.round((bounds[0] + bounds[2]) / 2);
        const cy = Math.round((bounds[1] + bounds[3]) / 2);
        lines.push(`${clickable ? '*' : ' '} "${text || desc}" @ ${cx},${cy}`);
      }
      console.log(lines.join('\n') || '(这屏没有文字控件)');
      console.log(`\nxml: ${p}`);
      break;
    }
    case 'open': {
      ensureDevice();
      const target = rest[0];
      if (target.includes('/')) adb(['shell', 'am', 'start', '-n', target]);
      else adb(['shell', 'monkey', '-p', target, '-c', 'android.intent.category.LAUNCHER', '1']);
      console.log('opened ' + target);
      break;
    }
    case 'apps': {
      ensureDevice();
      const out = adb(['shell', 'pm', 'list', 'packages']);
      const kw = rest.join(' ').toLowerCase();
      const list = out.split(/\r?\n/).map((s) => s.replace('package:', '').trim()).filter(Boolean)
        .filter((s) => !kw || s.toLowerCase().includes(kw));
      console.log(list.join('\n'));
      break;
    }
    case 'home': case 'back': case 'wake': case 'sleep': {
      ensureDevice();
      const map = { home: 'KEYCODE_HOME', back: 'KEYCODE_BACK', wake: 'KEYCODE_WAKEUP', sleep: 'KEYCODE_SLEEP' };
      adb(['shell', 'input', 'keyevent', map[cmd]]);
      console.log(cmd);
      break;
    }
    default:
      console.log('命令: shot | tap | swipe | key | text | ui | open | apps | home | back | wake | sleep');
  }
} catch (e) {
  console.error('ERR ' + (e.stderr ? e.stderr.toString() : e.message));
  process.exit(1);
}
